#!/usr/bin/env python3
# =====================================================================
# GENERATE_POWER_LAW_FIGURE — POST‑PROCESSING FOR FIGURE 10
# 
# Description:
#   Reads gamma_crit_summary.csv (generated by extract_gamma_crit.py)
#   and generates the power‑law figure (log‑log plot) for the manuscript.
#   All points (including speed=4) are included in the fit.
#
# Version: 1.1
# Reference: Trouillefou, C.M. et al. (2026). Parametric resilience
#            in a closed ecological reactor: The Wood Wide Web as a
#            distributed PID controller for life support.
#            npj Microgravity (submitted).
# =====================================================================

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import sys

# ---------------------------------------------------------------------
# 1. Load data from gamma_crit_summary.csv
# ---------------------------------------------------------------------
try:
    df = pd.read_csv('gamma_crit_summary.csv')
except FileNotFoundError:
    print("❌ File gamma_crit_summary.csv not found.")
    print("   Please run extract_gamma_crit.py first.")
    sys.exit(1)

# Extract speed and gamma_crit (ALL points)
speeds_all = df['speed'].values
gamma_crit_all = df['gamma_crit'].values

# Use ALL points for the fit (including speed=4)
speeds = speeds_all
gamma_crit = gamma_crit_all

if len(speeds) < 2:
    print("❌ Not enough data points. Need at least 2 points.")
    sys.exit(1)

# ---------------------------------------------------------------------
# 2. Linear regression on log-log scale (ALL points)
# ---------------------------------------------------------------------
log_speeds = np.log10(speeds)
log_gamma = np.log10(gamma_crit)
pente, intercept = np.polyfit(log_speeds, log_gamma, 1)
alpha = -pente
A = 10**intercept

# Coefficient of determination (R²)
log_pred = pente * log_speeds + intercept
R2 = 1 - np.sum((log_gamma - log_pred)**2) / np.sum((log_gamma - np.mean(log_gamma))**2)

# ---------------------------------------------------------------------
# 3. Generate the plot
# ---------------------------------------------------------------------
speed_fit = np.logspace(np.log10(2), np.log10(200), 100)
gamma_fit = A * speed_fit**(-alpha)

# npj Microgravity style
plt.rcParams.update({
    'font.family': 'sans-serif',
    'font.sans-serif': ['Arial', 'Helvetica', 'DejaVu Sans'],
    'font.size': 7,
    'axes.titlesize': 9,
    'axes.labelsize': 8,
    'legend.fontsize': 6.5,
    'xtick.labelsize': 7,
    'ytick.labelsize': 7,
    'lines.linewidth': 1.0,
    'lines.markersize': 5,
    'axes.linewidth': 0.8
})

fig, ax = plt.subplots(figsize=(3.5, 3.5))

# All data points (no exclusion)
ax.loglog(speeds, gamma_crit, 'o', markerfacecolor='black', markeredgecolor='black',
          zorder=5, label='Data points')

# Power-law fit
ax.loglog(speed_fit, gamma_fit, '--', color='#CC0000', linewidth=1.2, zorder=4,
          label=f'γ_crit = {A:.2f} · speed$^{{-{alpha:.2f}}}$\nR² = {R2:.3f}')

ax.set_xlabel('Signal speed factor')
ax.set_ylabel('γ_crit (20 % threshold)')
ax.legend(loc='upper right', frameon=True, edgecolor='gray')
ax.grid(True, which='major', linestyle='-', linewidth=0.3, alpha=0.5)
ax.grid(True, which='minor', linestyle=':', linewidth=0.2, alpha=0.3)
ax.minorticks_on()
ax.set_xlim(3, 200)
ax.set_ylim(0.04, 1.5)

plt.tight_layout()
fig.savefig('Figure10_power_law_final.png', dpi=600)
fig.savefig('Figure10_power_law_final.pdf', format='pdf')
plt.close(fig)

print("✅ Figure 10 generated: Figure10_power_law_final.png and .pdf")
print(f"   Fit: γ_crit = {A:.2f} · speed^(-{alpha:.2f}), R² = {R2:.3f}")